import { createSlice, nanoid } from "@reduxjs/toolkit";

const initialState = {
  templateId: "",
  publicLink: "",
  profileImg:
    "data:image/jpeg;base64,",
  backCoverImg:
    "data:image/jpeg;base64,",
  logoImg:
    "data:image/png;base64,",
  firstName: "Jon",
  lastName: "Doe",
  jobTitle: "Job Title",
  businessName: "Business Name",
  businessAddress: "21, Main Street, Opp. Royal Farm, Mall Road.",
  businessDescription: "Business Description",
  primaryActions: [
    {
      _id: "mobile",
      value: "+121234567890",
    },
    {
      _id: "email",
      value: "info@company.com",
    },
  ],
  secondaryActions: [],
  sections: [
    {
      _id: nanoid(),
      sectionName: "Products",
      subSections: [
        {
          _id: nanoid(),
          image:
            "data:image/jpeg;base64,",
          heading: "PHeading",
        },
      ],
    },
  ],
  colors: {
    buttonBg: undefined,
    background: undefined,
    text: undefined,
    buttonText: undefined,
    cardBg: undefined,
    cardText: undefined,
    // cardSeparator: undefined,
    cardIcon: undefined,
    featureText: undefined,
    featureSeparator: undefined,
    footerBg: undefined,
    footerIcon: undefined,
    qrCode: undefined,
  },
};

export const cardSlice = createSlice({
  name: "card",
  initialState,
  reducers: {
    setTemplateId: (state, action) => {
      state.templateId = action.payload;
    },
    publicLink: (state, action) => {
      state.publicLink = action.payload;
    },

    // Header Attachments
    profileImg: (state, action) => {
      state.profileImg = action.payload;
    },
    backCoverImg: (state, action) => {
      state.backCoverImg = action.payload;
    },

    // Contact Information
    logoImg: (state, action) => {
      state.logoImg = action.payload;
    },
    firstName: (state, action) => {
      state.firstName = action.payload;
    },
    lastName: (state, action) => {
      state.lastName = action.payload;
    },
    jobTitle: (state, action) => {
      state.jobTitle = action.payload;
    },
    businessName: (state, action) => {
      state.businessName = action.payload;
    },
    businessAddress: (state, action) => {
      state.businessAddress = action.payload;
    },
    businessDescription: (state, action) => {
      state.businessDescription = action.payload;
    },

    // Primary Action
    addPrimaryAction: (state, action) => {
      const { _id, value } = action.payload;
      state.primaryActions.push({ _id, value });
    },
    deletePrimaryAction: (state, action) => {
      const { _id } = action.payload;
      state.primaryActions = state.primaryActions.filter(
        (action) => action._id !== _id
      );
    },
    updatePrimaryAction: (state, action) => {
      const { _id, value } = action.payload;
      const primaryAction = state.primaryActions.find(
        (action) => action._id === _id
      );
      if (primaryAction) {
        primaryAction.value = value;
      }
    },

    // Secondary Action
    addSecondaryAction: (state, action) => {
      const { _id, value } = action.payload;
      state.secondaryActions.push({ _id, value });
    },
    deleteSecondaryAction: (state, action) => {
      const { _id } = action.payload;
      state.secondaryActions = state.secondaryActions.filter(
        (action) => action._id !== _id
      );
    },
    updateSecondaryAction: (state, action) => {
      const { _id, value } = action.payload;
      const secondaryAction = state.secondaryActions.find(
        (action) => action._id === _id
      );
      if (secondaryAction) {
        secondaryAction.value = value;
      }
    },

    // Feature Content
    addFeatureSection: (state) => {
      const section = {
        _id: nanoid(),
        sectionName: "",
        subSections: [
          {
            _id: nanoid(),
            image: null,
            heading: "",
          },
        ],
      };
      state.sections.push(section);
    },
    addFeatureSubSection: (state, action) => {
      const { sectionId } = action.payload;
      const section = state.sections.find(
        (section) => section._id === sectionId
      );
      if (section) {
        const subSection = {
          _id: nanoid(),
          image: null,
          heading: "",
        };
        section.subSections.push(subSection);
      }
    },
    updateSectionName: (state, action) => {
      const { sectionId, sectionName } = action.payload;
      const section = state.sections.find(
        (section) => section._id === sectionId
      );
      if (section) {
        section.sectionName = sectionName;
      }
    },
    updateSubSection: (state, action) => {
      const { sectionId, subSectionId, image, heading } = action.payload;
      const section = state.sections.find(
        (section) => section._id === sectionId
      );
      if (section) {
        const subSection = section.subSections.find(
          (subSection) => subSection._id === subSectionId
        );
        if (subSection) {
          subSection.image = image;
          subSection.heading = heading;
        }
      }
    },
    deleteFeatureSection: (state, action) => {
      const { sectionId } = action.payload;
      state.sections = state.sections.filter(
        (section) => section._id !== sectionId
      );
    },
    deleteFeatureSubSection: (state, action) => {
      const { sectionId, subSectionId } = action.payload;
      const section = state.sections.find(
        (section) => section._id === sectionId
      );
      if (section) {
        section.subSections = section.subSections.filter(
          (subSection) => subSection._id !== subSectionId
        );
      }
    },

    // Color
    reButtonBg: (state, action) => {
      state.colors.buttonBg = action.payload;
    },
    reBackground: (state, action) => {
      state.colors.background = action.payload;
    },
    reText: (state, action) => {
      state.colors.text = action.payload;
    },
    reButtonText: (state, action) => {
      state.colors.buttonText = action.payload;
    },
    reCardBg: (state, action) => {
      state.colors.cardBg = action.payload;
    },
    reCardText: (state, action) => {
      state.colors.cardText = action.payload;
    },
    // reCardSeparator: (state, action) => {
    //   state.colors.cardSeparator = action.payload;
    // },
    reCardIcon: (state, action) => {
      state.colors.cardIcon = action.payload;
    },
    reFeatureText: (state, action) => {
      state.colors.featureText = action.payload;
    },
    reFeatureSeparator: (state, action) => {
      state.colors.featureSeparator = action.payload;
    },
    reFooterBg: (state, action) => {
      state.colors.footerBg = action.payload;
    },
    reFooterIcon: (state, action) => {
      state.colors.footerIcon = action.payload;
    },
    reQrCode: (state, action) => {
      state.colors.qrCode = action.payload;
    },
  },
});

export const {
  setTemplateId,
  publicLink,
  profileImg,
  backCoverImg,
  logoImg,
  firstName,
  lastName,
  jobTitle,
  businessName,
  businessAddress,
  businessDescription,
  addPrimaryAction,
  deletePrimaryAction,
  updatePrimaryAction,
  addSecondaryAction,
  deleteSecondaryAction,
  updateSecondaryAction,
  addFeatureSection,
  addFeatureSubSection,
  updateSectionName,
  updateSubSection,
  deleteFeatureSection,
  deleteFeatureSubSection,
  reButtonBg,
  reBackground,
  reText,
  reButtonText,
  reCardBg,
  reCardText,
  // reCardSeparator,
  reCardIcon,
  reFeatureText,
  reFeatureSeparator,
  reFooterBg,
  reFooterIcon,
  reQrCode,
} = cardSlice.actions;

export default cardSlice.reducer;
